Record AArch32_SErrorSyndrome  :=
  { AArch32_SErrorSyndrome_AET : bits 2; AArch32_SErrorSyndrome_ExT : bits 1; }.
Arguments AArch32_SErrorSyndrome : clear implicits.
Notation "{[ r 'with' 'AArch32_SErrorSyndrome_AET' := e ]}" :=
  match r with Build_AArch32_SErrorSyndrome _ f1 => Build_AArch32_SErrorSyndrome e f1 end.
Notation "{[ r 'with' 'AArch32_SErrorSyndrome_ExT' := e ]}" :=
  match r with Build_AArch32_SErrorSyndrome f0 _ => Build_AArch32_SErrorSyndrome f0 e end.
#[export] Instance dummy_AArch32_SErrorSyndrome  : Inhabited (AArch32_SErrorSyndrome ) := {
  inhabitant := {|
    AArch32_SErrorSyndrome_AET := inhabitant;
    AArch32_SErrorSyndrome_ExT := inhabitant
|} }.


