Definition set_regval (reg_name : string) (v : register_value) (s : regstate) : option regstate :=
  if string_dec reg_name "STACK_LIMIT" then option_map (fun v => STACK_LIMIT_ref.(write_to) v s) (STACK_LIMIT_ref.(of_regval) v) else
  if string_dec reg_name "STACK_BASE" then option_map (fun v => STACK_BASE_ref.(write_to) v s) (STACK_BASE_ref.(of_regval) v) else
  if string_dec reg_name "HEAP_LIMIT" then option_map (fun v => HEAP_LIMIT_ref.(write_to) v s) (HEAP_LIMIT_ref.(of_regval) v) else
